const form = document.getElementById('quiz-form');
const scoreElement = document.querySelector('[data-testid="quiz-score"]');
const answers = { q1: 'b', q2: 'c', q3: 'b' };

form.addEventListener('submit', function (event) {
  event.preventDefault();
  let score = 0;
  Object.keys(answers).forEach(function (question) {
    const selected = form.querySelector('input[name="' + question + '"]:checked');
    if (selected && selected.value === answers[question]) score += 1;
  });
  scoreElement.textContent = String(score);
  scoreElement.dataset.score = String(score);
});
